def number_of_unique_good_subsequences(binary):
    mod = 1_000_000_007
    ending_zero = ending_one = 0
    has_zero = 0
    for digit in binary:
        if digit == '1':
            ending_one = (ending_zero + ending_one + 1) % mod
        else:
            ending_zero = (ending_zero + ending_one) % mod
            has_zero = 1
    return (ending_zero + ending_one + has_zero) % mod

